'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var logpmf = require( './../src/main.c' );


// FIXTURES //

var data = require( './fixtures/julia/data.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof logpmf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `NaN` if provided a `NaN`', function test( t ) {
	var y;

	y = logpmf( NaN, 10, 5, 2 );
	t.equal( isnan( y ), true, 'returns NaN' );

	y = logpmf( 0.0, NaN, 5, 2 );
	t.equal( isnan( y ), true, 'returns NaN' );

	y = logpmf( 0.0, 10, NaN, 2 );
	t.equal( isnan( y ), true, 'returns NaN' );

	y = logpmf( 0.0, 10, 5, NaN );
	t.equal( isnan( y ), true, 'returns NaN' );

	t.end();
});

tape( 'the function returns `-Infinity` if provided a population size `N` which is not a positive integer', function test( t ) {
	var y;

	y = logpmf( 2.0, 0, 5, 2 );
	t.equal( y, Number.NEGATIVE_INFINITY, 'returns -Infinity' );

	y = logpmf( 2.0, -10, 5, 2 );
	t.equal( y, Number.NEGATIVE_INFINITY, 'returns -Infinity' );

	t.end();
});

tape( 'the function returns `-Infinity` if provided a subpopulation size `K` which is not a nonnegative integer less than or equal to `N`', function test( t ) {
	var y;

	y = logpmf( 2.0, 10, -1, 2 );
	t.equal( y, Number.NEGATIVE_INFINITY, 'returns -Infinity' );

	y = logpmf( 2.0, 10, 20, 2 );
	t.equal( y, Number.NEGATIVE_INFINITY, 'returns -Infinity' );

	t.end();
});

tape( 'the function returns `-Infinity` if provided a number of draws `n` which is not a nonnegative integer less than or equal to `N`', function test( t ) {
	var y;

	y = logpmf( 2.0, 10, 5, -1 );
	t.equal( y, Number.NEGATIVE_INFINITY, 'returns -Infinity' );

	y = logpmf( 2.0, 10, 5, 20 );
	t.equal( y, Number.NEGATIVE_INFINITY, 'returns -Infinity' );

	t.end();
});

tape( 'the function returns `-Infinity` if provided an `x` which is not a nonnegative integer less than or equal to `min(n,K)`', function test( t ) {
	var y;

	y = logpmf( -1.0, 10, 5, 2 );
	t.equal( y, Number.NEGATIVE_INFINITY, 'returns -Infinity' );

	y = logpmf( 3.0, 10, 5, 2 );
	t.equal( y, Number.NEGATIVE_INFINITY, 'returns -Infinity' );

	t.end();
});

tape( 'the function returns expected value', function test( t ) {
	var expected;
	var delta;
	var tol;
	var x;
	var N;
	var K;
	var n;
	var y;
	var i;

	expected = data.expected;
	x = data.x;
	N = data.N;
	K = data.K;
	n = data.n;
	for ( i = 0; i < x.length; i++ ) {
		y = logpmf( x[i], N[i], K[i], n[i] );
		if ( y === expected[i] ) {
			t.equal( y, expected[i], 'x: '+x[i]+'. N: '+N[i]+'. K: '+K[i]+'. n: '+n[i]+'. y: '+y+'. expected: '+expected[i]+'.' );
		} else {
			delta = Math.abs( y - expected[i] );
			tol = 1.0e-12 * Math.abs( expected[i] );
			t.ok( delta <= tol, 'within tolerance. x: '+x[i]+'. N: '+N[i]+'. K: '+K[i]+'. n: '+n[i]+'. y: '+y+'. E: '+expected[i]+'. Δ: '+delta+'. tol: '+tol+'.' );
		}
	}
	t.end();
});
